async function handleLogin(env) {
  const problem = configProblem(env);
  if (problem) return driveNotReadyPage();
  const params = new URLSearchParams({
    client_id: env.GOOGLE_CLIENT_ID,
    redirect_uri: REDIRECT_URI,
    response_type: "code",
    scope: OAUTH_SCOPE,
    access_type: "offline",
    prompt: "consent",
  });
  return Response.redirect("https://accounts.google.com/o/oauth2/v2/auth?" + params.toString(), 302);
}

async function handleCallback(env, url) {
  const problem = configProblem(env);
  if (problem) return driveNotReadyPage();
  const oauthError = url.searchParams.get("error");
  if (oauthError) {
    return json({ error: "oauth_denied", message: "Google trả lỗi: " + oauthError }, 400);
  }
  const code = url.searchParams.get("code");
  if (!code) return json({ error: "missing_code", message: "Thiếu mã đăng nhập từ Google." }, 400);

  const tokenRes = await fetch(TOKEN_URL, {
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      code,
      client_id: env.GOOGLE_CLIENT_ID,
      client_secret: env.GOOGLE_CLIENT_SECRET,
      redirect_uri: REDIRECT_URI,
      grant_type: "authorization_code",
    }),
  });
  const tokens = await tokenRes.json().catch(() => ({}));
  if (!tokenRes.ok || !tokens.access_token) {
    return json(
      { error: "token_exchange_failed", message: "Đổi mã lấy token thất bại: " + (tokens.error_description || tokens.error || tokenRes.status) },
      502,
    );
  }

  let email = "";
  try {
    const infoRes = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
      headers: { authorization: "Bearer " + tokens.access_token },
    });
    const info = await infoRes.json().catch(() => ({}));
    email = info.email || "";
  } catch { /* email để trống nếu userinfo lỗi */ }

  const previous = await getRecord(env);
  const record = {
    refresh_token: tokens.refresh_token || (previous && previous.refresh_token) || "",
    email: email || (previous && previous.email) || "",
    accessToken: tokens.access_token,
    accessExp: Date.now() + (Number(tokens.expires_in) || 3600) * 1000,
    updatedAt: new Date().toISOString(),
  };
  if (!record.refresh_token) {
    return json(
      { error: "no_refresh_token", message: "Google không cấp refresh token. Hãy thu hồi quyền cũ của ứng dụng trong tài khoản Google rồi đăng nhập lại." },
      502,
    );
  }
  await saveRecord(env, record);

  // Cookie phiên: id ngẫu nhiên -> cùng bản ghi, để trình duyệt "đã đăng nhập".
  const sessionId = crypto.randomUUID();
  await env.AUTH.put("session:" + sessionId, JSON.stringify(record), { expirationTtl: 60 * 60 * 24 * 30 });
  return new Response(null, {
    status: 302,
    headers: {
      location: "/",
      "set-cookie": "ds_session=" + sessionId + "; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=2592000",
    },
  });
}

async function handleStatus(env, request) {
  const problem = configProblem(env);
  if (problem) return json({ connected: false, error: "not_configured", message: problem });
  const record = (await getRecord(env)) || (await getSessionRecord(env, request));
  if (!record || !record.refresh_token) return json({ connected: false });
  try {
    await getAccessToken(env, record); // làm mới token nếu sắp hết hạn
    return json({ connected: true, email: record.email || "" });
  } catch {
    return json({ connected: false, email: record.email || "", error: "token_invalid" });
  }
}

// Cầu token cho trang: trên workers.dev, trang xin access token từ phiên
// đăng nhập phía máy chủ (cookie ds_session) để tự chạy các tính năng Drive
// trong trang (đồng bộ, duyệt file, tải báo cáo…) thay cho luồng GIS dán
// Client ID. Refresh token KHÔNG bao giờ rời máy chủ — trang chỉ nhận
// access token ngắn hạn.
async function handleDriveToken(env, request) {
  const problem = configProblem(env);
  if (problem) return json({ connected: false, error: "not_configured", message: problem });
  const session = await getSessionRecord(env, request);
  if (!session || !session.refresh_token) {
    return json({
      connected: false,
      error: "no_session",
      message: "Chưa có phiên đăng nhập qua máy chủ — hãy bấm “Kết nối Google Drive”.",
    });
  }
  // Ưu tiên bản ghi chính drive:main (refreshAccessToken ghi token mới vào đó);
  // bản ghi phiên trong KV chỉ là bản sao lúc đăng nhập.
  const main = await getRecord(env);
  const record = main && main.refresh_token ? main : session;
  try {
    const accessToken = await getAccessToken(env, record);
    const expiresIn = Math.max(0, Math.round(((record.accessExp || Date.now()) - Date.now()) / 1000));
    return json({
      connected: true,
      access_token: accessToken,
      expires_in: expiresIn,
      email: record.email || session.email || "",
    });
  } catch {
    return json({ connected: false, error: "token_invalid", email: record.email || session.email || "" });
  }
}

// Mọi endpoint /api/drive/* đều cần bản ghi đăng nhập còn hiệu lực.
async function requireDrive(env) {
  const problem = configProblem(env);
  if (problem) return { errorResponse: json({ error: "not_configured", message: problem }, 503) };
  const record = await getRecord(env);
  if (!record || !record.refresh_token) {
    return { errorResponse: json({ error: "not_connected", message: "Chưa kết nối Google Drive — hãy bấm “Kết nối Google Drive”." }, 401) };
  }
  return { record };
}

async function handleDriveFiles(env, url) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  const q = (url.searchParams.get("q") || "").trim();
  const folder = (url.searchParams.get("folder") || "").trim();
  const clauses = ["trashed = false"];
  if (q) clauses.push("name contains '" + escapeQ(q) + "'");
  else if (folder) clauses.push("'" + escapeQ(folder) + "' in parents");
  else clauses.push("'root' in parents");
  const params = new URLSearchParams({
    q: clauses.join(" and "),
    fields: "files(id,name,mimeType,modifiedTime,size,parents),nextPageToken",
    orderBy: "folder,name",
    pageSize: "100",
  });
  const res = await driveFetch(env, record, DRIVE_API + "/files?" + params.toString());
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  return json(data);
}

async function findFileByName(env, record, name, parentId) {
  const clauses = ["name = '" + escapeQ(name) + "'", "trashed = false"];
  if (parentId) clauses.push("'" + escapeQ(parentId) + "' in parents");
  const params = new URLSearchParams({
    q: clauses.join(" and "),
    fields: "files(id,name,mimeType,modifiedTime)",
    pageSize: "1",
  });
  const res = await driveFetch(env, record, DRIVE_API + "/files?" + params.toString());
  if (!res.ok) return null;
  const data = await res.json().catch(() => ({}));
  return data.files && data.files.length ? data.files[0] : null;
}

async function handleDriveUpload(env, request) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  let body;
  try {
    body = await request.json();
  } catch {
    return json({ error: "bad_json", message: "Thân yêu cầu phải là JSON." }, 400);
  }
  const name = (body.name || "").trim();
  const mimeType = (body.mimeType || "text/plain; charset=utf-8").trim();
  const parentId = (body.parentId || "").trim();
  const contentText = typeof body.contentText === "string" ? body.contentText : "";
  if (!name) return json({ error: "missing_name", message: "Thiếu tên file." }, 400);

  const existing = await findFileByName(env, record, name, parentId);
  if (existing) {
    // Cập nhật đúng file cũ (chỉ thay nội dung) — không tạo bản trùng.
    const res = await driveFetch(env, record, DRIVE_UPLOAD_API + "/files/" + existing.id + "?uploadType=media", {
      method: "PATCH",
      headers: { "content-type": mimeType },
      body: contentText,
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
    }
    return json({ ...data, updated: true });
  }

  const metadata = { name };
  if (parentId) metadata.parents = [parentId];
  const boundary = "doc-sach-" + crypto.randomUUID();
  const multipart =
    "--" + boundary + "\r\n" +
    "content-type: application/json; charset=utf-8\r\n\r\n" +
    JSON.stringify(metadata) + "\r\n" +
    "--" + boundary + "\r\n" +
    "content-type: " + mimeType + "\r\n\r\n" +
    contentText + "\r\n" +
    "--" + boundary + "--";
  const res = await driveFetch(env, record, DRIVE_UPLOAD_API + "/files?uploadType=multipart", {
    method: "POST",
    headers: { "content-type": "multipart/related; boundary=" + boundary },
    body: multipart,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  return json({ ...data, created: true });
}

async function handleDriveDownload(env, url) {
  const { record, errorResponse } = await requireDrive(env);
  if (errorResponse) return errorResponse;
  const id = (url.searchParams.get("id") || "").trim();
  if (!id) return json({ error: "missing_id", message: "Thiếu id file." }, 400);
  const res = await driveFetch(env, record, DRIVE_API + "/files/" + encodeURIComponent(id) + "?alt=media");
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    return json({ error: "drive_error", message: (data.error && data.error.message) || ("Drive trả lỗi " + res.status) }, 502);
  }
  const headers = new Headers();
  headers.set("content-type", res.headers.get("content-type") || "application/octet-stream");
  const len = res.headers.get("content-length");
  if (len) headers.set("content-length", len);
  return new Response(res.body, { status: 200, headers });
}

// ---------------------------------------------------------------------------
// Cloud-link import: tải file từ link CHIA SẺ CÔNG KHAI của Google Drive /
// OneDrive (không cần đăng nhập). Worker đóng vai trò proxy để trình duyệt
// không bị chặn CORS và để qua được trang xác nhận của Drive. Thân file
// được stream thẳng, không nạp toàn bộ vào bộ nhớ.
// ---------------------------------------------------------------------------

const CLOUD_BROWSER_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

function cloudStreamResponse(res) {
  const headers = new Headers();
  headers.set("content-type", res.headers.get("content-type") || "application/octet-stream");
  const disp = res.headers.get("content-disposition");
  if (disp) headers.set("content-disposition", disp);
  const len = res.headers.get("content-length");
  if (len) headers.set("content-length", len);
  headers.set("Access-Control-Allow-Origin", "*");
  return new Response(res.body, { status: res.status, headers });
}

function base64UrlEncodeText(str) {
  const bytes = new TextEncoder().encode(str);
  let bin = "";
  bytes.forEach((b) => { bin += String.fromCharCode(b); });
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function base64UrlDecodeText(s) {
  let b64 = String(s).replace(/-/g, "+").replace(/_/g, "/");
  while (b64.length % 4) b64 += "=";
  const bin = atob(b64);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

async function handleCloudDrive(url) {
  const id = (url.searchParams.get("id") || "").trim();
  if (!/^[A-Za-z0-9_-]{10,80}$/.test(id)) {
    return json({ error: "Mã file Google Drive không hợp lệ." }, 400);
  }
  const target = "https://drive.usercontent.google.com/download?id=" + encodeURIComponent(id) + "&export=download&confirm=t";
  const res = await fetch(target, {
    headers: { "User-Agent": CLOUD_BROWSER_UA },
    redirect: "follow",
  });
  const ct = (res.headers.get("content-type") || "").toLowerCase();
  if (!res.ok || ct.indexOf("text/html") !== -1) {
    return json({ error: "Không tải được file từ Google Drive (link chưa chia sẻ công khai hoặc file quá lớn)." }, 502);
  }
  return cloudStreamResponse(res);
}

async function handleCloudOneDrive(url) {
  const share = (url.searchParams.get("share") || "").trim();
  if (!share) return json({ error: "Thiếu tham số share của OneDrive." }, 400);
  let shareUrl;
  try {
    shareUrl = base64UrlDecodeText(share);
  } catch {
    return json({ error: "Tham số share của OneDrive không hợp lệ." }, 400);
  }
  let parsed;
  try {
    parsed = new URL(shareUrl);
  } catch {
    return json({ error: "Link OneDrive không hợp lệ." }, 400);
  }
  const host = parsed.hostname.toLowerCase();
  const hostOk = host === "onedrive.live.com" || host === "1drv.ms" || host.endsWith(".sharepoint.com");
  if (parsed.protocol !== "https:" || !hostOk) {
    return json({ error: "Link OneDrive không hợp lệ." }, 400);
  }
  const token = "u!" + base64UrlEncodeText(shareUrl);
  const res = await fetch("https://api.onedrive.com/v1.0/shares/" + token + "/root/content", {
    headers: { "User-Agent": CLOUD_BROWSER_UA },
    redirect: "follow",
  });
  if (!res.ok) {
    return json({ error: "Không tải được file từ OneDrive (link chưa chia sẻ công khai?)." }, 502);
  }
  return cloudStreamResponse(res);
}

async function handleCloudDownload(env, url) {
  try {
    const provider = (url.searchParams.get("provider") || "").trim().toLowerCase();
    if (provider === "drive") return await handleCloudDrive(url);
    if (provider === "onedrive") return await handleCloudOneDrive(url);
    return json({ error: "Nhà cung cấp đám mây chưa được hỗ trợ." }, 400);
  } catch (err) {
    return json({ error: "Lỗi máy chủ khi tải file." }, 500);
  }
}

// MEGA public-link support. The page cannot rely on reaching
// api.mega.co.nz directly from every network, so the Worker relays
// the two calls; the file key never leaves the user's page and the
// decryption happens there — the Worker only sees ciphertext.
async function handleMegaApi(request) {
  try {
    const body = await request.text();
    // Only the single public-file info command is allowed through.
    let parsed;
    try {
      parsed = JSON.parse(body);
    } catch {
      return json({ error: "Yêu cầu MEGA không hợp lệ." }, 400);
    }
    if (!Array.isArray(parsed) || parsed.length !== 1
        || !parsed[0] || parsed[0].a !== "g"
        || typeof parsed[0].p !== "string" || !/^[A-Za-z0-9_-]{6,20}$/.test(parsed[0].p)) {
      return json({ error: "Yêu cầu MEGA không hợp lệ." }, 400);
    }
    const sid = Math.floor(Math.random() * 1e9).toString();
    const res = await fetch("https://api.mega.co.nz/cs?id=" + sid, {
      method: "POST",
      headers: { "content-type": "application/json", "User-Agent": CLOUD_BROWSER_UA },
      body: JSON.stringify(parsed),
    });
    const text = await res.text();
    return new Response(text, {
      status: res.status,
      headers: { "content-type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  } catch (err) {
    return json({ error: "Không nối được tới MEGA." }, 502);
  }
}

async function handleMegaDownload(url) {
  try {
    const u = base64UrlDecodeText((url.searchParams.get("u") || "").trim());
    const parsed = new URL(u);
    const host = parsed.hostname.toLowerCase();
    if (parsed.protocol !== "https:"
        || !(host === "mega.co.nz" || host.endsWith(".mega.co.nz"))) {
      return json({ error: "Địa chỉ tải MEGA không hợp lệ." }, 400);
    }
    const res = await fetch(u, { headers: { "User-Agent": CLOUD_BROWSER_UA } });
    if (!res.ok) {
      return json({ error: "Không tải được dữ liệu từ MEGA." }, 502);
    }
    return cloudStreamResponse(res);
  } catch (err) {
    return json({ error: "Không tải được dữ liệu từ MEGA." }, 502);
  }
}

// ---------------------------------------------------------------------------

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    try {
      if (path === "/auth/login") return await handleLogin(env);
      if (path === "/auth/callback") return await handleCallback(env, url);
      if (path === "/api/status") return await handleStatus(env, request);
      if (path === "/api/drive/token" && request.method === "GET") return await handleDriveToken(env, request);
      if (path === "/api/drive/files" && request.method === "GET") return await handleDriveFiles(env, url);
      if (path === "/api/drive/upload" && request.method === "POST") return await handleDriveUpload(env, request);
      if (path === "/api/drive/download" && request.method === "GET") return await handleDriveDownload(env, url);
      if (path === "/api/cloud/download" && request.method === "GET") return await handleCloudDownload(env, url);
      if (path === "/api/cloud/mega" && request.method === "POST") return await handleMegaApi(request);
      if (path === "/api/cloud/mega-dl" && request.method === "GET") return await handleMegaDownload(url);
      if (path.startsWith("/api/") || path.startsWith("/auth/")) {
        return json({ error: "not_found", message: "Không có endpoint này." }, 404);
      }
      return servePage(); // mọi đường còn lại -> trang đọc sách (SPA fallback)
    } catch (err) {
      return json({ error: "server_error", message: String((err && err.message) || err) }, 500);
    }
  },

  // Quét nền mỗi 5 phút: làm mới token để phiên Drive không chết, ghi mốc
  // quét cuối. Đây là móc để chạy hàng đợi đồng bộ Drive ở các bước sau.
  async scheduled(event, env, ctx) {
    const sweep = async () => {
      if (!env.AUTH) return;
      const record = await getRecord(env);
      if (record && record.refresh_token && env.GOOGLE_CLIENT_ID && env.GOOGLE_CLIENT_SECRET) {
        try { await refreshAccessToken(env, record); } catch { /* token lỗi sẽ báo ở /api/status */ }
      }
      await env.AUTH.put(LAST_SWEEP_KEY, new Date().toISOString());
    };
    if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(sweep());
    else await sweep();
  },
};
